**Root cause:** the chi router mounted the SPA fallback `r.Get("/*")` with no `/docs` routes, so every `/docs*` request fell through to the catch-all and returned `index.html` (or 404) — the spec was never reachable.

**Fix:** a `DocsHandler` registered **before** the SPA fallback, plus a spec-resolution ladder mirroring `resolveDistDir`. Key code from `openapi.go`:

```go
// Register mounts the docs routes. MUST be called before the SPA
// catch-all, otherwise r.Get("/*") swallows /docs.
func (h *DocsHandler) Register(r chi.Router) {
    r.Get("/docs", h.ScalarPage)
    r.Get("/docs/openapi.yaml", h.RawSpec)
    r.Get("/docs/*", h.Subpath)
}

// ScalarPage renders the Scalar viewer (CDN) pointed at the local spec.
func (h *DocsHandler) ScalarPage(w http.ResponseWriter, r *http.Request) {
    w.Header().Set("Content-Type", "text/html; charset=utf-8")
    w.WriteHeader(http.StatusOK)
    io.WriteString(w, docsHTML) // <script id="api-reference" data-url="/docs/openapi.yaml">
                                // <script src="https://cdn.jsdelivr.net/npm/@scalar/api-reference"></script>
}

// RawSpec streams the spec verbatim; path resolved per request.
func (h *DocsHandler) RawSpec(w http.ResponseWriter, r *http.Request) {
    specPath, ok := resolveSpecPath()
    if !ok {
        writeJSON(w, http.StatusNotFound, map[string]string{"error": "openapi spec not found"})
        return
    }
    data, err := os.ReadFile(specPath)
    if err != nil { writeJSON(w, http.StatusInternalServerError, ...); return }
    w.Header().Set("Content-Type", "application/yaml; charset=utf-8")
    w.Write(data)
}

// Subpath: /docs/ → 301 /docs; anything else → JSON 404.
func (h *DocsHandler) Subpath(w http.ResponseWriter, r *http.Request) {
    switch rest := chi.URLParam(r, "*"); rest {
    case "/", "":
        http.Redirect(w, r, "/docs", http.StatusMovedPermanently)
    default:
        writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found", "path": r.URL.Path})
    }
}

// Spec resolution: ASCE_API_SPEC env override, then a CWD-candidate
// ladder — the exact pattern resolveDistDir uses for the SPA dist dir.
func resolveSpecPath() (string, bool) {
    if p := os.Getenv("ASCE_API_SPEC"); p != "" {
        if info, err := os.Stat(p); err == nil && !info.IsDir() {
            abs, _ := filepath.Abs(p)
            return abs, true
        }
        return p, false
    }
    for _, c := range []string{"api/openapi.yaml", "./api/openapi.yaml",
        "../api/openapi.yaml", "../../api/openapi.yaml"} {
        if info, err := os.Stat(c); err == nil && !info.IsDir() {
            abs, _ := filepath.Abs(c)
            return abs, true
        }
    }
    return "api/openapi.yaml", false
}
```

Router wiring in `main.go` — ordering is the whole fix:

```go
func NewRouter() chi.Router {
    r := chi.NewRouter()
    NewDocsHandler().Register(r)          // /docs, /docs/openapi.yaml, /docs/*
    if distDir, ok := resolveDistDir(); ok {
        r.Get("/*", spaHandler(distDir).ServeHTTP)   // SPA fallback, AFTER docs
    } else {
        r.Get("/*", http.NotFoundHandler().ServeHTTP)
    }
    return r
}
```

`api/openapi.yaml` is generated at 3455 lines (valid OpenAPI 3.0.3, 33 paths, 23 schemas) via `scripts/gen-spec.py`.
